""" xor 2 bytearray

        Args:
            b1 -- bytearray
            b2 -- bytearray

        return a bytearray
    """
def bytearray_xor(b1: Any, b2: Any) -> object {
    result = bytearray();
    for (x, y) in zip(b1, b2) {
        result.append((x ^ y));
    }
    return result;
}

